import sys

def find_a_b(x):
    # Check if x can be expressed as (a + b) / 2
    if x % 2 != 0:
        return -1

    # Calculate a and b
    a = x
    b = x

    # Check if a and b satisfy the XOR condition
    if (a ^ b) == x:
        return a, b
    else:
        return -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []

    index = 1
    for _ in range(t):
        x = int(data[index])
        result = find_a_b(x)
        results.append(result)
        index += 1

    for result in results:
        if result == -1:
            print(-1)
        else:
            a, b = result
            print(a, b)

if __name__ == "__main__":
    main()
